INSERT INTO items (title, tags, author, hot_score, ctr, publish_time, url, summary) VALUES
('打卡“雪龙2”号（记录中国）','财经,finance','人民网',23.6,0.0497,NOW()-INTERVAL 35 HOUR,'http://finance.people.com.cn/n1/2025/0605/c1004-40494067.html','市民在“雪龙2”号飞行平台上合影留念。">　　市民在“雪龙2”号飞行平台上合影留念。　　“雪龙2”号停泊于海口秀英港码头。　　以上图片均为苏弼坤摄（影像中国）">　　“雪龙2”号停泊于海口秀英港码头。　　以上图片均为苏弼坤摄（影像中国）　　6月2日，海南海口秀英港码头，市民登上“雪龙2”号，参观实验室、办公区、船员起居室、驾驶台、飞行平台等区域。“雪龙2”号是中国首艘自主建造的极地科考破冰船。 　'),
('两年后，“办不成事”反映窗口变“冷清”了（干部状态新观察·走进一线探作风）','时政,politics','人民网',55.7,0.0621,NOW()-INTERVAL 43 HOUR,'http://politics.people.com.cn/n1/2025/0603/c458474-40492814.html','编者按：习近平总书记指出，党的作风是党的形象，是观察党群干群关系、人心向背的晴雨表。当前，深入贯彻中央八项规定精神学习教育正在全党开展，各地进一步增强持续抓好作风建设的高度自觉，着力整治形式主义突出问题，树牢正确政绩观，用心用情用力办好民生实事。 本版今起推出“干部状态新观察·走进一线探作风”系列报道，关注各地切实纠“四风”、转作风、树新风，推动重心下移、资源下沉，以优良作风凝心聚力、干事创业的实'),
('从作物迁徙看全球历史','娱乐,ent','人民网',97.8,0.1075,NOW()-INTERVAL 32 HOUR,'http://ent.people.com.cn/n1/2025/0604/c1012-40493357.html','《世界文明中的作物迁徙》：白馥兰等著，于楠译；中国科学技术出版社出版。">　　《世界文明中的作物迁徙》：白馥兰等著，于楠译；中国科学技术出版社出版。 　　在历史的长河中，作物不仅是人类生存的物质基础，更是经济交流与文化传播的重要载体。《世界文明中的作物迁徙》以作物为跨地域交流的见证者，梳理作物迁徙的历史脉络，探寻其背后的经济、社会、文化等多重因素，揭示作物迁徙与世界历史发展之间的内在关联，为读者理'),
('世界女排联赛北京站明日开赛 新一届中国女排即将亮相','娱乐,ent','人民网',22.8,0.1612,NOW()-INTERVAL 28 HOUR,'http://ent.people.com.cn/n1/2025/0603/c1012-40493125.html','人民网北京6月3日电 （记者胡雪蓉）2025年世界女排联赛中国北京站将于6月4日至8日在国家体育馆进行。中国女排新任主教练赵勇今天在接受采访时表示，希望球队通过比赛能不断取得进步。 今年世界女排联赛分站赛将于6月4日至7月14日举行，中国女排将参加中国北京、中国香港、美国阿灵顿三站分站赛。根据赛程安排，中国女排将在北京站先后迎战比利时队、波兰队、法国队和土耳其队。 新一届中国女排于4月10日正式组'),
('环赛里木湖公路自行车赛第三赛段卢绍轩勇夺赛段冠军','娱乐,ent','人民网',48.5,0.0202,NOW()-INTERVAL 49 HOUR,'http://ent.people.com.cn/n1/2025/0604/c1012-40493474.html','中国新疆第十七届环赛里木湖（国际）公路自行车赛暨中国自行车运动骑游大会2日展开第三赛段的角逐，来自百锐腾车队的卢绍轩凭借团队的默契配合勇夺赛段桂冠。 该赛段全程90公里，起始点为博州全民健身中心·文化艺术中心，选手们沿G219一路向西骑行，途经博乐市阿热勒托海牧场及温泉县安格里格镇，最终抵达温泉县体育场。 该赛段海拔从450米爬升至1331米，属于缓上坡赛段，考验车手们的耐力和体能。比赛前半程，大'),
('首批39个地方特色食品产业获重点培育，有你的家乡吗？','财经,finance','人民网',26.7,0.0646,NOW()-INTERVAL 26 HOUR,'http://finance.people.com.cn/n1/2025/0605/c1004-40494616.html','人民网北京6月5日电 （记者申佳平）据工业和信息化部官网消息，经省级工业和信息化主管部门推荐、专家评价、网上公示等程序，工业和信息化部确定了传统优势食品产区和地方特色食品产业重点培育名单（第一批），包括北京二锅头清香型白酒、哈尔滨红肠、江西山茶油、云南小粒咖啡等39个地方特色食品产业及其所在传统优势食品产区。 工业和信息化部消费品工业司表示，传统优势食品产区和地方特色食品产业重点培育名单是中国消费'),
('山东广饶县开展防范非法集资宣传进养老机构活动','财经,finance','人民网',39.9,0.1442,NOW()-INTERVAL 12 HOUR,'http://finance.people.com.cn/n1/2025/0605/c460498-40494704.html','为深入贯彻落实防范非法金融活动宣传月活动，切实维护老年人合法权益，增强老年人防范意识和识别能力，6月4日，广饶县金稳办联合县民政局、县公安局，走进萱花开颐养中心和康泰阳光老年公寓，开展了以“守住钱袋子 护好幸福家”为主题的老年人防范非法集资和养老诈骗专项宣传活动。  本次宣传活动聚焦老年人群体，通过发放宣传资料、涉非风险提示、典型案例警示、防非技巧展示等方式，重点围绕非法集资的特征、危害、常见手法'),
('气排球爱好者齐聚梅河口 共享全民健身盛宴','体育,sports','人民网',41.1,0.0344,NOW()-INTERVAL 52 HOUR,'http://sports.people.com.cn/n1/2024/0818/c14820-40300895.html','新华社长春8月17日电 17日，为期4天的吉林省第二届全国气排球精英邀请赛暨第16个“全民健身日”主题周系列活动开幕式在吉林省梅河口举行。 　　本届邀请赛共有来自全国108支代表队的1000余名运动员参加。比赛设置了男子、女子青年组和中年组，以及中年混合组和老年混合组六个组别。  　　吉林省第二届全国气排球精英邀请赛开幕式。 主办方供图 　　开幕式上，女排奥运冠军颜妮作为特邀嘉宾来到现场，与气排球'),
('文化中国行 | 赣水竞楫激千浪','娱乐,ent','人民网',66.9,0.083,NOW()-INTERVAL 39 HOUR,'http://ent.people.com.cn/n1/2025/0603/c1012-40492754.html','端午之际，江西省分宜县举办的龙舟赛事一个接一个，“江西村舟·分宜电厂螺蛳杯”赣西地区首届龙舟邀请赛刚刚落下帷幕，“龙腾天工·江西村舟·分宜电厂螺蛳杯”端午龙舟赛又接续登场。 分宜是千年古县，流传着划龙舟的传统。据《洋江乡志》记载，“分宜西邑，袁水纵贯之，端阳，民竞舟于其上，万人空巷”，生动描绘了当时龙舟竞渡的盛大场景。 赛前，在赣江支流袁河之上和次支流杨溪河上，龙舟一条条下水操练，“咚咚咚咚”的锣'),
('网络安全小黑板 | 我的隐私谁做主？不得不看的网络安全四大问题','科技,it','人民网',44.3,0.0572,NOW()-INTERVAL 68 HOUR,'http://it.people.com.cn/n1/2021/1008/c433780-32247548.html','万物互联时代，网民的个人手机、电脑、可穿戴设备等信息化设备都接入网络。随着个人信息不断被各种采集，这些看起来零散的数据被汇总、挖掘、分析，也就是大数据的商业化，每个人几乎变成了“透明人”，这些数据有可能被不正当使用、披露或泄露，由此引发公众对于隐私权的担忧。网络个人隐私安全该如何防护？  防偷拍  案例解析  各类偷拍事件接连发生，不法人员集中在酒店、卫生间、试衣间等位置安装针孔摄像头，对个人隐私'),
('奋力谱写网络强国建设精彩华章我国网信事业发展成就综述','科技,it','人民网',88.3,0.0448,NOW()-INTERVAL 50 HOUR,'http://it.people.com.cn/n1/2021/1008/c433780-32247535.html','信息技术浪潮气象万千，数字经济发展生机勃勃。  　　 习近平总书记高度重视网络安全和信息化工作，提出一系列具有开创性意义的新思想新观点新论断，形成了习近平总书记关于网络强国的重要思想。在这一重要思想指引下，我国网信事业取得积极进展和瞩目成就。  　　 积极构建安全清朗的精神家园  　　 聪者听于无声，明者见于未形。  　　 “没有网络安全就没有国家安全，就没有经济社会稳定运行，广大人民群众利益也难'),
('防范和打击非法金融活动部际联席会议召开2025年全体（扩大）会议暨打击非法集资专项行动推进会议','财经,finance','人民网',81.1,0.1353,NOW()-INTERVAL 64 HOUR,'http://finance.people.com.cn/n1/2025/0605/c460498-40494726.html','2025年防范和打击非法金融活动部际联席会议全体（扩大）会议暨打击非法集资专项行动推进会议4月10日在京召开。联席会议召集人、金融监管总局党委书记、局长李云泽出席会议并讲话。中央政法委副秘书长杨春雷通报相关情况，最高人民法院党组成员、副院长李勇，农业农村部党组成员、副部长张兴旺，中国人民银行党委委员、副行长陶玲，中国证监会党委委员、副主席李明，市场监管总局总工程师刘敏，公安部经济犯罪侦查局局长华列'),
('中国铁人三项运动迈入发展快车道','体育,sports','人民网',32.0,0.1359,NOW()-INTERVAL 19 HOUR,'http://sports.people.com.cn/n1/2019/0923/c383225-31367676.html','人民网北京9月23日电（王霞光 张素琦）2019年威海铁人三项世界杯赛日前在山东威海半月湾举行。缓坡半环的海滩上人声鼎沸，铁人们在浪花间奋力争先。此情此景，让中国铁人三项运动协会秘书长陈笑然感慨不已：“谁能想到这个蜚声海内外的铁三赛场，多年前只是一个简陋的养殖场，周围都是大片的荒地。如今，这里已成为威海房价最高的地段。” 从2008年在威海海滨浴场举办第一场铁人三项比赛，威海已经和铁人三项结缘12'),
('2020年我国预计人均体育场地面积2.20平方米','体育,sports','人民网',23.5,0.1536,NOW()-INTERVAL 66 HOUR,'http://sports.people.com.cn/n1/2021/0301/c14820-32039330.html','人民网北京3月1日电 （记者杨磊）2月28日，国家统计局公布了中华人民共和国2020年国民经济和社会发展统计公报。  2020年，我国全民健身理念深入人心，体育健身设施不断完善，群众体育蓬勃发展。公报显示，年末全国共有体育场地371.3万个，体育场地面积31.0亿平方米，预计人均体育场地面积2.20平方米。全年我国运动员在3个运动大项中获得4个世界冠军，共创1项世界纪录。全年我国残疾人运动员在6项'),
('2021国家网络安全宣传周重大活动日程','科技,it','人民网',70.2,0.1374,NOW()-INTERVAL 65 HOUR,'http://it.people.com.cn/n1/2021/1008/c433780-32247599.html','2021网安周重要活动  一、开幕式  时间：10月11日09:00  地点：西安国际会展中心会议楼三层多功能厅  主办单位：中央宣传部、中央网信办、教育部、工业和信息化部、公安部、中国人民银行、国家广电总局、全国总工会、共青团中央、全国妇联  承办单位：西安市人民政府  二、重要活动  （一）网络安全博览会  主题：网络安全为人民，网络安全靠人民  1.实体线下展  时间：2021年10月8日起'),
('国家网络安全宣传周上海品牌活动 网络安全嘉年华开幕','科技,it','人民网',31.1,0.1038,NOW()-INTERVAL 65 HOUR,'http://it.people.com.cn/n1/2021/1008/c433780-32247565.html','10月7日，2021年国家网络安全宣传周上海地区“网络安全嘉年华”主会场活动在松江云间粮仓开幕。嘉年华活动从10月7日至10日每天举办。  　　 智慧城市为人们提供了更智能、更便利的生活环境，但便利的网络环境以及个人信息的公开，必然会带来各种各样的网络威胁。嘉年华现场设置了“网络安全威胁体验区”，让市民在体验中增强网络安全意识，提升网络安全技能。  　　 2021年是中国共产党成立100周年，今年'),
('CBA全明星赛首发球员票数公布 郭艾伦当选票王','体育,sports','人民网',65.5,0.1501,NOW()-INTERVAL 3 HOUR,'http://sports.people.com.cn/n1/2021/0226/c14820-32037810.html','人民网北京2月26日电 （记者郝帅） 2月26日，CBA官方公布了2020-21赛季CBA联赛全明星首发名单。广东队的赵睿和辽宁队的郭艾伦分别以188370票和231553票荣登南、北区票王。值得一提的是，这也是郭艾伦首次当选联盟票王。  名单显示，北区的韩德君、张镇麟、郭艾伦和赵继伟同为辽宁队球员，南区的周鹏、任骏飞、赵睿、胡明轩也同样来自广东。如此一来，辽宁队和广东队一共有8人入选本赛季全明星'),
('银河系的未来是一部“变形记”','财经,finance','人民网',86.1,0.1134,NOW()-INTERVAL 30 HOUR,'http://finance.people.com.cn/n1/2025/0604/c1004-40493702.html','在浩瀚无垠的宇宙中，银河系——我们的家园，正缓缓沿轨迹移动。与它相伴的是邻近的仙女星系、三角座星系与大麦哲伦星系。长久以来，天文学家一直认为，在大约50亿年后，银河系将不可避免地与仙女星系发生碰撞，并最终合并为一个全新的星系“Milkomeda”。但现在人们发现，银河系的未来宛如一部“变形记”，会比之前想象的更加多变且不确定。 芬兰赫尔辛基大学天文学家利用盖亚望远镜和哈勃望远镜，对银河系未来的运动'),
('联通数字科技有限公司在京成立','科技,it','人民网',26.8,0.0267,NOW()-INTERVAL 47 HOUR,'http://it.people.com.cn/n1/2021/0208/c1009-32025735.html','2月7日，联通数字科技有限公司（以下简称“联通数科”）揭牌仪式在京举行。中国联通董事长王晓初、总经理陈忠岳、党组副书记李福申、副总经理买彦州、副总经理梁宝俊、总会计师朱可炳、副总经理范云军、纪检监察组组长董群、副总经理何飚等出席揭牌仪式。  　　王晓初表示，在“十四五”开局之年，中国联通大力整合“云、大、物、智、链、安”（云计算、大数据、物联网、人工智能、区块链、安全）等能力，组建联通数科公司，既'),
('主教练张晓欢：我们是亲历者 也是幸运者','体育,sports','人民网',96.8,0.0803,NOW()-INTERVAL 58 HOUR,'http://sports.people.com.cn/n1/2024/0818/c14820-40300891.html','在刚刚落幕的巴黎奥运会上，中国花游队包揽了集体和双人项目的两枚金牌，实现了花游项目的历史性突破。从8月12日启程回国已近一周，三年多来持续不断的压力得到了缓冲和释放，中国队夺得首枚奥运花游金牌的喜悦，梦想照进现实的快乐，让北京青年报记者对中国花游队主教练张晓欢专访时，仍然能够感觉到她那种释怀、骄傲和幸福的情绪。张晓欢说：“几代花游人的努力、艰苦付出和传承，无数前辈的奥运冠军梦想，在我和我的队员们手'),
('三部门加密网络安全围栏 首次从产品视角管理漏洞','科技,it','人民网',64.7,0.1204,NOW()-INTERVAL 69 HOUR,'http://it.people.com.cn/n1/2021/1008/c433780-32247587.html','工业和信息化部、国家互联网信息办公室、公安部近日联合印发《网络产品安全漏洞管理规定》（以下简称《规定》），该《规定》自今年9月1日起开始施行。  　　志翔科技高级副总裁伍海桑对科技日报记者说：“《规定》是对《网络安全法》的细化，进一步规范了网络产品的漏洞发现、公布、报告和修补等流程，明确了职责、对象和办法，是网络安全法落地实施的环节，非常必要，而且也非常务实。”  　　这是我国首次从产品视角管理漏'),
('文脉华章丨中华优秀传统文化是中华民族的文化根脉','时政,politics','人民网',74.5,0.0983,NOW()-INTERVAL 1 HOUR,'http://politics.people.com.cn/n1/2025/0603/c1001-40493087.html','“中华优秀传统文化是中华民族的文化根脉”“决不能抛弃中华优秀传统文化这个根脉”……党的十八大以来，习近平总书记多次以“根脉”喻指中华优秀传统文化，并对为什么坚守、坚守什么、怎样坚守文化根脉作出了一系列重要论述。大象新闻为您梳理，我们一起学习。'),
