SET NAMES utf8mb4;
CREATE DATABASE IF NOT EXISTS recommend DEFAULT CHARSET utf8mb4;
USE recommend;

-- 用户表（用户名/邮箱均可登录）
CREATE TABLE IF NOT EXISTS users (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    username VARCHAR(64) NOT NULL UNIQUE,
    email VARCHAR(128) DEFAULT NULL UNIQUE,
    password VARCHAR(128) NOT NULL,
    interest_tags VARCHAR(256) DEFAULT '' COMMENT '兴趣标签,逗号分隔',
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP
);

-- 新闻表
CREATE TABLE IF NOT EXISTS items (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    title VARCHAR(512) NOT NULL,
    tags VARCHAR(256) DEFAULT '' COMMENT '频道/分类标签',
    author VARCHAR(128) DEFAULT '' COMMENT '来源媒体',
    hot_score DOUBLE DEFAULT 0,
    ctr DOUBLE DEFAULT 0.05,
    publish_time DATETIME DEFAULT CURRENT_TIMESTAMP,
    url VARCHAR(1024) DEFAULT NULL COMMENT '原文链接',
    UNIQUE KEY uk_url (url(512)),
    summary TEXT COMMENT '内容摘要',
    INDEX idx_tags (tags),
    INDEX idx_hot (hot_score)
);

-- 行为表
CREATE TABLE IF NOT EXISTS behaviors (
    id BIGINT PRIMARY KEY AUTO_INCREMENT,
    user_id BIGINT NOT NULL,
    item_id BIGINT NOT NULL,
    action VARCHAR(16) NOT NULL,
    event_id VARCHAR(64) NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY uk_event (event_id),
    INDEX idx_user (user_id)
);

-- 收藏表
CREATE TABLE IF NOT EXISTS favorites (
    user_id BIGINT NOT NULL,
    item_id BIGINT NOT NULL,
    created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
    PRIMARY KEY (user_id, item_id)
);

-- 精排权重（支持热修改）
CREATE TABLE IF NOT EXISTS rank_config (
    id INT PRIMARY KEY,
    w_ctr DOUBLE DEFAULT 0.4,
    w_interest DOUBLE DEFAULT 0.3,
    w_hot DOUBLE DEFAULT 0.2,
    w_fresh DOUBLE DEFAULT 0.1,
    updated_at DATETIME DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP
);


